class C:
 @property
 def __dict__(self): return [7]
c=C()
print(vars(c)[0])
try: c.__dict__={}
except AttributeError: print("readonly")

events=[]
class D:
 def __get__(self,obj,owner):
  events.append("get")
  return [obj]
 def __set__(self,obj,value): events.append("set")
 def __delete__(self,obj): events.append("delete")
class C: __dict__=D()
c=C()
print(vars(c)[0] is c)
c.__dict__={}
del c.__dict__
print(events[0],events[1],events[2])

class C:
 def __getattribute__(self,name):
  if name=="__dict__": return [7]
  return object.__getattribute__(self,name)
c=C()
print(vars(c)[0])
d=object.__getattribute__(c,"__dict__")
d["tag"]=9
print(c.tag,d is object.__getattribute__(c,"__dict__"))

class C:
